-- Stock adjustments capture source/destination, while assignment changes remain automatic.
create or replace function private.log_resource_stock_movement()
returns trigger language plpgsql security definer set search_path=public as $$
declare d int;rd int;kind text;qty int;why text;
begin d:=new.quantity_available-old.quantity_available;rd:=new.quantity_reserved-old.quantity_reserved;if d=0 and rd=0 then return new;end if;
 kind:=case when rd>0 and d<0 then'reserved'when rd<0 and d>0 then'released'when rd<0 and d=0 then'used'when d>0 then'received'else'used'end;qty:=greatest(abs(d),abs(rd));why:=coalesce(nullif(current_setting('resqnet.reason',true),''),case kind when'reserved'then'Reserved for rescue assignment'when'released'then'Released from rescue assignment'when'used'then'Used or removed from inventory'else'Inventory received'end);
 insert into public.resource_movements(resource_id,movement_type,quantity,source_location,destination_location,reason,actor_id)values(new.id,kind,qty,nullif(current_setting('resqnet.source_location',true),''),nullif(current_setting('resqnet.destination_location',true),''),why,auth.uid());return new;end $$;

create or replace function public.admin_adjust_resource_v2(p_resource_id uuid,p_delta int,p_reason text,p_source text default null,p_destination text default null)
returns public.resources language plpgsql security definer set search_path=public as $$declare r public.resources;v_reason text:=nullif(trim(coalesce(p_reason,'')),'');begin if not private.is_admin()then raise exception'Administrator access required';end if;if v_reason is null then raise exception'A reason is required to change stock';end if;if coalesce(p_delta,0)=0 then raise exception'Quantity change cannot be zero';end if;select * into r from public.resources where id=p_resource_id for update;if not found then raise exception'Resource not found';end if;if r.quantity_available+p_delta<0 then raise exception'Not enough stock: only % available',r.quantity_available;end if;
 perform set_config('resqnet.reason',v_reason,true);perform set_config('resqnet.source_location',coalesce(trim(p_source),''),true);perform set_config('resqnet.destination_location',coalesce(trim(p_destination),''),true);update public.resources set quantity_available=quantity_available+p_delta,updated_at=now()where id=p_resource_id returning * into r;
 insert into public.audit_logs(actor,actor_user_id,actor_role,action,entity_type,entity_id,new_values,reason)values('admin',auth.uid(),'admin','resource_adjusted','resource',p_resource_id,jsonb_build_object('quantity_available',r.quantity_available,'delta',p_delta,'source',p_source,'destination',p_destination),v_reason);return r;end $$;
revoke execute on function public.admin_adjust_resource_v2(uuid,int,text,text,text)from public,anon;grant execute on function public.admin_adjust_resource_v2(uuid,int,text,text,text)to authenticated;
